void GameView::stream() {
    if(auto result=streaming_->poll()){if(!result->error.empty())throw std::runtime_error("Scene streaming failed: "+result->error);if(result->assets){data_->assets->adopt(*result->assets);streamUpload_=true;}}
    if(streamUpload_){auto deadline=GetTickCount64()+4;while(GetTickCount64()<deadline && data_->assets->uploadOne(renderer_)){}if(data_->assets->uploaded()==data_->assets->uploadCount()){data_->assets->ready(renderer_);streamUpload_=false;}}
    std::vector<std::string> models,textures;auto sky=data_->session->world()->environment().skyModel;if(!sky.empty() && !data_->assets->cachedModel(sky))models.push_back(sky);for(auto& [id,u]:data_->session->units()){if(!u->model.empty() && !data_->assets->cachedModel(u->model))models.push_back(u->model);if(!u->icon.empty() && u->icon!="_" && !data_->assets->hasImage(u->icon))textures.push_back(u->icon);}for(auto& [id,item]:data_->session->items()){if(!item->model.empty() && !data_->assets->cachedModel(item->model))models.push_back(item->model);if(!item->icon.empty() && item->icon!="_" && !data_->assets->hasImage(item->icon))textures.push_back(item->icon);}for(auto id:selected()){for(auto& button:data_->session->commands(id,data_->session->localPlayer().value_or(0)))if(!button.icon.empty() && button.icon!="_" && !data_->assets->hasImage(button.icon))textures.push_back(button.icon);for(auto& job:data_->session->units().at(id)->production){auto& info=data_->session->product(job.type);if(!info.icon.empty() && info.icon!="_" && !data_->assets->hasImage(info.icon))textures.push_back(info.icon);}}if(!models.empty() || !textures.empty())streaming_->request(models,textures,data_->assets->textureNames());
}
