    label(L"菜单 (F10)",.02f,.004f,.012f);auto chosen=selected();if(!chosen.empty()){auto& u=*data_->session->units().at(chosen.front());auto icon=data_->assets->cachedTexture(u.icon);if(icon)quad(.19f,.465f,.055f,.055f,0xffffffff,icon);label(wide(u.name),.27f,.463f,.014f);label(std::to_wstring(int(number(u.life)))+L" / "+std::to_wstring(int(number(u.maxLife))),.27f,.49f,.012f,0xff55ff55);if(number(u.maxMana)>0)label(std::to_wstring(int(number(u.mana)))+L" / "+std::to_wstring(int(number(u.maxMana))),.27f,.509f,.012f,0xff7777ff);commandPanel(input,chosen.front());}
